WITH point_geom AS (
  SELECT ST_SetSRID(ST_MakePoint(-82.760985, 36.173714), 4326)::geography AS geom
),
clipped_dem AS (
  SELECT ST_Clip(rast, true, (SELECT geom FROM point_geom)::geometry, true) AS clipped_rast
  FROM public.dem_us
  WHERE ST_Intersects(rast, (SELECT geom FROM point_geom)::geometry)
)
SELECT 
  (SELECT MAX(ST_Value(clipped_rast, 1)) FROM clipped_dem) > 280 AS exceeds_280_meters;

